function show_name(uuid) {
    for (var i = 0; i < database.length; i++) {
        if (uuid == database[i].uuid) {
            return database[i].name;
        }
    }
    return "";
}

function show_doc(uuid) {
    for (var i = 0; i < database.length; i++) {
        if (uuid == database[i].uuid) {
            return database[i].doc || "N/A";
        }
    }
    return "N/A";
}

function show_gfn(uuid) {
    for (var i = 0; i < database.length; i++) {
        if (uuid == database[i].uuid) {
            return database[i].gfn || "N/A";
        }
    }
    return "N/A";
}

// ข้อมูลจาก payload
var data = msg.payload;
var error_text = "";
var time_now = Date.now();
var lasttime_error = flow.get(uidKey) || 0;
var text_line = "";
msg.check_send_noti = 0;

// ตรวจสอบ Blacklist (uuid + error_text)
var data_backlist = flow.get("data_backlist") || [];

// ตรวจสอบ UUID ใน database
var isValidUUID = database.some(item => item.uuid === uid[1]);

// ถ้า UUID ถูกต้องและมี error
if (isValidUUID && data[13] != 0 && data[0] == 100 && (data[1] != 61 && data[1] != 62 && data[1] != 63) &&
    (time_now - lasttime_error >= 10  * 60 * 1000) // แจ้งทุก 10 นาที
) {
// if (isValidUUID && data[13] != 0 && (time_now - lasttime_error >= 1 * 60 * 1000) && data[0] == 100 && (data[1] != 61 && data[1] != 62 && data[1] != 63) ) {

    // แปลงรหัส error เป็นข้อความ
    switch (data[13]) {
        case 1: error_text = "ARC"; break;
        case 2: error_text = "LEAKAGE CURRENT"; break;
        case 4: error_text = "UNDER VOLTAGE"; break;
        case 8: error_text = "OVER VOLTAGE"; break;
        case 16: error_text = "OVER CURRENT"; break;
        case 32: error_text = "SHORT CIRCUIT"; break;
        case 64: error_text = "OVER TEMP"; break;
        case 128: error_text = "EQ"; break;
        case 67: error_text = "Send Order Arc Alarm"; break;
        case 65: error_text = "Send Order SC Alarm"; break;
        case 14: error_text = "Fault trip : " + data[13] + " , " + data[14]; break;
    }
    var isBlacklisted = data_backlist.some(item => item.uuid === uid[1] && item.error === error_text);

    if (!isBlacklisted && error_text !== "" && data[1] != 67) {
        text_line = "### 📍 HOME SPEAK\n" +
            "**📌 N :** " + show_name(uid[1]) + "\n" +
            "**🔌 U :** " + uid[1] + "\n" +
            "**⚠️ E :** " + error_text + "\n" +
            "**🔗 D :** [ดูข้อมูล](" + show_doc(uid[1]) + ")\n" +
            "**🔗 L :** [Grafana](" + show_gfn(uid[1]) + ")";

        msg.check_send_noti = 1;

        msg.datalog = {
            uid: uid[1],
            project: "HOME SPEAK",
            name: show_name(uid[1]),
            error: error_text
        };

        msg.payload = text_line;
        msg.channel = "1349996053453209691";
                // msg.channel = "1370322520485400618";

        flow.set(uidKey, Date.now());
        return msg;
    }
} 
// ============ ตรวจสอบ OFFLINE (แยกออกมาจากด้านบน) ==============
flow.set('CHK_uidHS' + uid[1] + ".timestamp", Date.now());
let offlineThreshold = 10 * 60 * 1000;
for (let i = 0; i < database.length; i++) {
    let device = database[i];
    if (!device || !device.uuid) continue;

    let lastTime = flow.get('CHK_uidHS' + device.uuid + ".timestamp") || 0;

    if (time_now - lastTime > offlineThreshold) {
        let isBlacklistedOffline = data_backlist.some(item => item.uuid === device.uuid && item.error === "OFFLINE");

        if (!isBlacklistedOffline) {
            let lastNotify = flow.get('notiOffline_' + device.uuid) || 0;
            if (time_now - lastNotify >= 10 * 60 * 1000) {
                flow.set('notiOffline_' + device.uuid, time_now);

                let offline_msg = "====================\n";
                offline_msg += "📍 **" + device.name + "**\n";
                offline_msg += "🔑 UUID : " + device.uuid + "\n";
                offline_msg += "⚠️ STATUS : OFFLINE\n";
                offline_msg += "📄 Doc : " + device.doc + "\n";
                offline_msg += "📊 Dashboard : " + device.gfn + "\n";
                offline_msg += "====================";

                msg.payload = offline_msg;
                msg.channel = "1366346925368152156";                 
                // msg.channel = "1370322520485400618";

                msg.check_send_noti = 1;
                return msg; // ส่ง offline แล้วหยุด
            }
        }
    }
}

