var hours = nowTH.getUTCHours();
var minutes = nowTH.getUTCMinutes();
var nowMin = hours * 60 + minutes;

/* ================= TIME CONFIG ================= */
const OPEN_TIME  = 22 * 60 + 5;  // 22:05
const CLOSE_TIME = 14 * 60;      // 14:00

/*
  14:00 → 22:05 = OFF
  22:05 → 14:00 = ON (ข้ามวัน)
*/
var shouldStatus;
if (nowMin >= CLOSE_TIME && nowMin < OPEN_TIME) {
    shouldStatus = 0; // OFF
} else {
    shouldStatus = 1; // ON
}

