    if (!lasttime_error || (time_now - lasttime_error >= tenMinutes)) {

        var problem =
            (shouldStatus === 0)
                ? "ควรปิด (14:00) แต่ยังเปิดอยู่ ❌"
                : "ควรเปิด (22:05) แต่ปิดอยู่ ❌";

